                                                    items={Array.from({ length: 3 }).map((_unused, index) => () => (
                                                        <Skeleton key={index} className="h-16 w-full rounded-xl" />
                                                    ))}
                                                />
                                            </CardContent>
                                        </Card>
                                    ),
