    )
}

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import type { QuizSessionReadinessData, QuizSessionWeakTagData } from "@/modules/api/graphql/mutations/types/complete-flashcard-quiz-session"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import type { SkeletonProps } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { Container } from "@/components/frames/Container"
import { StackV } from "@/components/frames/Stack"
import { Grid } from "@/components/frames/Grid"
import { RecapEnrollUpsell, RecapReadinessCallout, RecapWeakTagsCard } from "./recapBlocks"

/** How many placeholder rows the per-card breakdown shows on the FIRST load (outer `isSkeleton`, results count unknown yet). */
const SKELETON_ROW_COUNT = 5

/** One already-resolved per-card breakdown row — status tone + aria label + score chip text, built by the connected {@link import("./index").FlashcardQuizResult}. */
export interface FlashcardQuizResultPerCardRow {
    /** Stable React key (`${cardId}-${index}`). */
    key: string
    /** Card front text, or the already-translated fallback when the card text hasn't resolved. */
    title: string
    /** Pass/partial/fail tone for the status dot + score chip. */
    tone: "success" | "warning" | "danger"
    /** Already-translated aria-label for the status dot ("Fully correct" / "Partially correct" / "Incorrect"). */
    statusLabel: string
    /** Already-translated "n/m" score chip text. */
    scoreLabel: string
}

/** Props for {@link _FlashcardQuizResult} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardQuizResultProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no session to show (not found / not owned) → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch — re-runs the session fetch. */
    onRetry?: () => void
    /** Returns to the flashcards overview — the empty-branch action AND the closing CTA. */
    onBack: () => void

    breadcrumbLabel: string
    headerTitle: string
    headerDescription: string
    /** Shared title for both the error branch and the not-found empty branch (same text on both, existing behaviour). */
    fallbackTitle: string
    backToReviewLabel: string

    /** Final coverage (0..1), or `null` on a session with nothing to judge yet. */
    coverage?: number | null
    xpEarned?: number
    fullyCorrectCount?: number
    cardCount?: number
    coverageLabel: string
    xpLabel: string
    fullyCorrectLabel: string

    /** Whether today's daily XP cap clamped the grant (live path only). */
    dailyCapReached?: boolean
    dailyCapReachedLabel: string

    /** Whether the persisted session has any per-card results to break down. */
    hasPerCardResults?: boolean
    /** The per-card card-text fetch's own first-load flag (a NESTED async region, independent of the outer session load). */
    isPerCardSkeleton?: boolean
    /** Row count for the per-card skeleton once the outer session HAS resolved (`min(results.length, 5)`). */
    perCardSkeletonCount?: number
    perCardRows?: Array<FlashcardQuizResultPerCardRow>
    perCardHeading: string

    enrolled?: boolean
    enrollKnown?: boolean

    /** Top-3 weakest tags (state "empty" when none qualify). */
    topWeakTags?: Array<QuizSessionWeakTagData>
    /** Tags beyond the top-3, scrolled inside the same card. */
    overflowWeakTags?: Array<QuizSessionWeakTagData>
    /** Resolves a weak tag to its lesson route, or `null` when the mapping was ambiguous. */
    resolveTagHref?: (tag: QuizSessionWeakTagData) => string | null
    genericContinueHref?: string

    studyHeading: string
    /** Course id for the RAG "study this" child block. */
    courseId: string
    /** Course display id — needed for the same child's deep links. */
    courseDisplayId: string

    /** AI Mock Interview readiness (live path only, enrolled-only). */
    readiness?: QuizSessionReadinessData | null
    mockInterviewHref?: string
}

/** Status-dot tone → the class it paints (§4/§5: a bare decorative dot, sized+coloured once). */
const STATUS_DOT_CLASS: Record<"success" | "warning" | "danger", string> = {
    success: "size-2.5 shrink-0 rounded-full bg-success",
    warning: "size-2.5 shrink-0 rounded-full bg-warning",
    danger: "size-2.5 shrink-0 rounded-full bg-danger",
}

/**
 * A per-card breakdown row's leading status dot — colour carries the pass/partial/fail
 * tone, but never ALONE: `role="img"` + `aria-label` carry the same meaning for a
 * screen reader.
 */
const StatusDot = ({ tone, label }: StatusDotProps) => (
    <span className={STATUS_DOT_CLASS[tone]} role="img" aria-label={label} />
)

/**
 * The URL-addressable RESULT surface for a finished "Quick quiz" run — the presentational
 * half of {@link import("./index").FlashcardQuizResult}. Mirrors
 * {@link import("../QuizSession/FlashcardQuizStats").FlashcardQuizStats}'s shell: a centered
 * `Container size="md"` column of canonical blocks — HERO = three metric tiles
 * (coverage · XP · fully-correct), the per-card cloze breakdown, the most-forgotten
 * tags, and a self-hiding RAG "study this" list keyed off those tags.
 *
 * Three states in the fixed order error → empty → content (`tiers/split.md`,
 * `loading-and-skeleton.md` §1): `error` falls to the shared `AsyncContentError` frame,
 * `isEmpty` to `AsyncContentEmpty`, and otherwise the ONE real tree renders with
 * `isSkeleton` threaded to every leaf that supports it. `PageHeader`/`BackLink` carry no
 * `isSkeleton` of their own (`missingSkeletonSupport`) but need none here — they render
 * static, already-translated chrome text, not fetched data, so they stay unconditional
 * across every branch (the original design's own choice, preserved). `RecapEnrollUpsell`
 * / `RecapWeakTagsCard` / `RecapReadinessCallout` / `RelatedContentList` also carry no
 * `isSkeleton` (`missingSkeletonSupport`) and, same as the original parallel skeleton
 * never drew them while loading, are gated behind `!isSkeleton` instead of mirrored.
 * `SurfaceCardList`'s `leading`/`meta` row slots do not auto-forward `isSkeleton`
 * (`missingSkeletonSupport`) — the per-card rows are built as two different item
 * arrays (skeleton vs real, `StatusDot`/bare `Skeleton` swapped in directly), the same
 * shape `FlashcardQuizStats` already uses for its own gap rows.
 *
 * See `tiers/split.md` — the connected `index.tsx` owns the two fetches (session +
 * per-card text), the redux enrollment reads, and every i18n string.
 *
 * @param props - {@link FlashcardQuizResultProps}
 */
export const _FlashcardQuizResult = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBack,
    breadcrumbLabel,
    headerTitle,
    headerDescription,
    fallbackTitle,
    backToReviewLabel,
    coverage = null,
    xpEarned = 0,
    fullyCorrectCount = 0,
    cardCount = 0,
    coverageLabel,
    xpLabel,
    fullyCorrectLabel,
    dailyCapReached = false,
    dailyCapReachedLabel,
    hasPerCardResults = false,
    isPerCardSkeleton = false,
    perCardSkeletonCount = 0,
    perCardRows = [],
    perCardHeading,
    enrolled = false,
    enrollKnown = false,
    topWeakTags = [],
    overflowWeakTags = [],
    resolveTagHref = () => null,
    genericContinueHref = "",
    studyHeading,
    courseId,
    courseDisplayId,
    readiness = null,
    mockInterviewHref = "",
}: FlashcardQuizResultProps) => {
    const coverageValue = coverage != null ? `${Math.round(coverage * 100)}%` : "—"
    const xpValue = `+${xpEarned}`
    const fullyCorrectValue = `${fullyCorrectCount}/${cardCount}`

    const header = () => (
        <PageHeader
            breadcrumb={<BackLink label={breadcrumbLabel} onPress={onBack} />}
            title={headerTitle}
            description={headerDescription}
        />
    )

    const body = () => {
        // error beats a stale loading flag; the not-found empty branch only reads once
        // settled — the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
        if (error) {
            return (
                <AsyncContentError
                    title={fallbackTitle}
                    onRetry={onRetry}
                    retryLabel={backToReviewLabel}
                />
            )
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={CheckCircleIcon}
                    title={fallbackTitle}
                    action={() => (
                        <Button size="sm" variant="primary" onPress={onBack} label={backToReviewLabel} />
                    )}
                />
            )
        }

        const showPerCard = isSkeleton || hasPerCardResults
        const perCardListSkeleton = isSkeleton || isPerCardSkeleton
        const perCardItems: Array<SurfaceCardListItem> = perCardListSkeleton
            ? Array.from({ length: isSkeleton ? SKELETON_ROW_COUNT : perCardSkeletonCount }, (_unused, index) => ({
                key: `pending-${index}`,
                leading: () => <Skeleton className="size-2.5 shrink-0 rounded-full" />,
                meta: () => <Chip isSkeleton />,
            }))
            : perCardRows.map((row) => ({
                key: row.key,
                title: row.title,
                leading: () => <StatusDot tone={row.tone} label={row.statusLabel} />,
                meta: () => <Chip tone={row.tone} text={row.scoreLabel} />,
            }))

        const showUpsell = !isSkeleton && enrollKnown && !enrolled
        const weakTagsPrimary = enrollKnown && enrolled
        const showStudyList = !isSkeleton && topWeakTags.length > 0
        const showReadiness = !isSkeleton && enrollKnown && enrolled && readiness != null

        return (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                // HERO — three authoritative metric tiles (outcome first).
                    () => (
                    // teacher-hold: flashcards-remain-quiz-result-metric-grid-gap4-no-token —
                    // peer metric tiles at preserved step 4; no card-grid token.
                        <Grid
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            columns={{ base: 1, sm: 3 }}
                            isSkeleton={isSkeleton}
                            items={[
                                {
                                    key: "coverage",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={coverageValue} label={coverageLabel} />
                                    ),
                                },
                                {
                                    key: "xp",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={xpValue} label={xpLabel} />
                                    ),
                                },
                                {
                                    key: "fullyCorrect",
                                    content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (
                                        cellSkeleton
                                            ? <MetricCard isSkeleton />
                                            : <MetricCard value={fullyCorrectValue} label={fullyCorrectLabel} />
                                    ),
                                },
                            ]}
                        />
                    ),
                    ...(!isSkeleton && dailyCapReached ? [() => (
                        <Typography size="xs" color="muted" text={dailyCapReachedLabel} />
                    )] : []),

                    // PER-CARD breakdown — a NESTED async region (its own card-text fetch),
                    // so it carries its own `isPerCardSkeleton` on top of the outer one.
                    ...(showPerCard ? [() => (
                        <SurfaceCardList
                            label={perCardHeading}
                            isSkeleton={perCardListSkeleton}
                            items={perCardItems}
                        />
                    )] : []),

                    // enroll upsell (trial only) — the result's PRIMARY action for a trial
                    // viewer, framed as a reward for the momentum just built.
                    ...(showUpsell ? [() => <RecapEnrollUpsell />] : []),

                    // weak-tags demand-bridge: PRIMARY when enrolled, a smaller secondary
                    // link under the upsell when trial.
                    ...(!isSkeleton ? [() => (
                        <RecapWeakTagsCard
                            weakTags={topWeakTags}
                            overflowWeakTags={overflowWeakTags}
                            resolveTagHref={resolveTagHref}
                            genericHref={genericContinueHref}
                            primary={weakTagsPrimary}
                        />
                    )] : []),

                    // quiet, self-hiding "study this too" — RAG search keyed off the same
                    // weak tags (no typing); auto-hides when there are none.
                    ...(showStudyList ? [() => (
                        <RelatedContentList
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            query={topWeakTags.map((tag) => tag.tag).join(" ")}
                            label={studyHeading}
                        />
                    )] : []),

                    // AI Mock Interview readiness — live-only (query-absent), enrolled-only.
                    ...(showReadiness ? [() => (
                        <RecapReadinessCallout
                            readiness={readiness as QuizSessionReadinessData}
                            mockInterviewHref={mockInterviewHref}
                        />
                    )] : []),

                    // onward path — never a dead end, even with no weak tags.
                    ...(!isSkeleton ? [() => (
                        <Button variant="tertiary" onPress={onBack} label={backToReviewLabel} classNames={["self-center"]} />
                    )] : []),
                ]} />
        )
    }

    return (
        <Container
            identity={{ tier: "block", component: "FlashcardQuizResult" }}
            size="md"
            padding={{ base: { x: 5, y: 6 }, sm: { x: 6 } }}
            body={() => <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[header, body]} />}
        />
    )
}

type StatusDotProps = { tone: "success" | "warning" | "danger"; label: string }

"use client"

import React, { useCallback } from "react"
import { Button, ScrollShadow, Typography } from "@heroui/react"
import { ArrowRightIcon, FlameIcon, LockIcon, MicrophoneStageIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { type QuizSessionReadinessData, type QuizSessionWeakTagData } from "@/modules/api/graphql/mutations/types/complete-flashcard-quiz-session"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCardRow } from "@/components/blocks/cards/SurfaceListCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"

/**
 * Shared "Quick quiz" recap/result blocks — LIFTED out of `QuizSession` so BOTH the
 * live end-of-run recap and the URL-addressable {@link import("./index").FlashcardQuizResult}
 * surface render the exact same components instead of duplicating them. Each block
 * is a self-contained conversion node (enroll upsell, weak-tags demand bridge, AI
 * Mock Interview readiness cross-link).
 */

/**
 * Recap Zone E — the enroll upsell shown ONLY to trial viewers, as the result's
 * PRIMARY action. Reads as an earned reward for the streak/XP the learner just
 * built — not a blocking paywall. Opens the shared course-enroll payment overlay.
 */
export const RecapEnrollUpsell = () => {
    const t = useTranslations()
    const { open } = usePaymentOverlayState()

    const onEnroll = useCallback(
        () => open({ flow: PaymentFlow.CourseEnroll }),
        [open],
    )

    return (
        <Box principle="page-pad" className="rounded-2xl border border-default bg-default px-6 py-8 text-center"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface.">
            <StackV gap={4} align="center" items={[
                () => <IconTile icon={<FlameIcon aria-hidden focusable="false" />} tone="accent" size="sm" />,
                () => (
                    <StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line — not label-field, because neither line is a form control label."
                        items={[
                            () => (
                                <Typography type="h4" weight="semibold">
                                    {t("flashcard.quiz.upsellTitle")}
                                </Typography>
                            ),
                            () => (
                                <Typography type="body-sm" color="muted">
                                    {t("flashcard.quiz.upsellDescription")}
                                </Typography>
                            ),
                        ]} />
                ),
                () => (
                    <Button
                        variant="primary"
                        size="lg"
                        className="mt-1 w-full max-w-xs"
                        onPress={onEnroll}
                    >
                        {t("flashcard.quiz.upsellCta")}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                    </Button>
                ),
            ]} />
        </Box>
    )
}

/** Props for {@link RecapWeakTagsCard}. */
export interface RecapWeakTagsCardProps {
    /** Top-3 weakest tags to always show (empty when nothing qualifies — state "empty"). */
    weakTags: Array<QuizSessionWeakTagData>
    /** Any tags beyond the top-3 — scrolled INSIDE this same card, never truncated silently
     *  and never a separate drawer (state "overflow"). */
    overflowWeakTags: Array<QuizSessionWeakTagData>
    /** Resolves a weak tag to its lesson route, or `null` when the deck→lesson mapping was
     *  ambiguous (falls back to `genericHref` for that row). */
    resolveTagHref: (tag: QuizSessionWeakTagData) => string | null
    /** Generic "continue learning" destination — the empty-state CTA AND the fallback for
     *  any weak tag whose lesson mapping was ambiguous. */
    genericHref: string
    /** Whether this card is the result's PRIMARY demand-bridge (enrolled viewers) or a
     *  smaller secondary link (trial viewers, where Zone E takes the primary slot instead). */
    primary: boolean
}

/** One weak-tag row: tag label + coverage + a "review this lesson" link. */
const WeakTagRow = ({
    tag,
    href,
}: WeakTagRowProps) => {
    const t = useTranslations()
    const router = useRouter()
    return (
        <SurfaceListCardRow
            title={tag.tag}
            subtitle={t("flashcard.quiz.weakTagCoverage", { percent: Math.round(tag.coverage * 100) })}
            trailing={() => (
                <StackH gap={2} principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="center" classNames={["shrink-0"]} items={[
                        () => <span className="text-sm font-medium text-accent-soft-foreground">{t("flashcard.quiz.reviewLesson")}</span>,
                        () => (
                            <ArrowRightIcon
                                aria-hidden
                                focusable="false"
                                className="size-4 transition-transform group-hover:translate-x-1"
                            />
                        ),
                    ]} />
            )}
            hover="underline"
            onPress={() => router.push(href)}
        />
    )
}

/**
 * Recap Zone C — the demand-bridge from "just played" to "go learn". Ranks the
 * session's weakest tags and links each straight back to the lesson that covers
 * it; falls back to a generic "keep learning" CTA when there's no weak-tag data
 * yet (first session, or the mapping was ambiguous). Overflow past the top-3
 * scrolls inside the same card via `ScrollShadow` — never a drawer.
 */
export const RecapWeakTagsCard = ({
    weakTags,
    overflowWeakTags,
    resolveTagHref,
    genericHref,
    primary,
}: RecapWeakTagsCardProps) => {
    const t = useTranslations()
    const router = useRouter()

    // no weak-tag data at all → the one, simple, generic bridge (state "empty"). When
    // this card IS the result's primary action (enrolled, no upsell competing), the CTA
    // is a full primary button; when it's demoted (trial), it's a standalone tertiary link.
    if (weakTags.length === 0) {
        return primary ? (
            <LabeledCard label={t("flashcard.quiz.weakTagsTitle")}>
                <StackV gap={4} items={[
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("flashcard.quiz.weakTagsEmpty")}
                        </Typography>
                    ),
                    () => (
                        <Button
                            variant="primary"
                            className="self-start"
                            onPress={() => router.push(genericHref)}
                        >
                            {t("flashcard.quiz.continueLearning")}
                            <ArrowRightIcon className="size-5" aria-hidden focusable="false" />
                        </Button>
                    ),
                ]} />
            </LabeledCard>
        ) : (
            <Button
                variant="tertiary"
                size="sm"
                className="self-start"
                onPress={() => router.push(genericHref)}
            >
                {t("flashcard.quiz.continueLearning")}
                <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
            </Button>
        )
    }

    // secondary (trial) rendering: a smaller link-style row, not the full card — Zone E
    // (enroll upsell) is the primary action instead (state "mixed (trial)"). Standalone,
    // no primary beside it → tertiary.
    if (!primary) {
        const first = weakTags[0]
        const firstHref = resolveTagHref(first) ?? genericHref
        return (
            <Button
                variant="tertiary"
                size="sm"
                className="self-start"
                onPress={() => router.push(firstHref)}
            >
                {t("flashcard.quiz.weakTagSecondaryLink", { tag: first.tag })}
                <ArrowRightIcon className="size-4" aria-hidden focusable="false" />
            </Button>
        )
    }

    return (
        <LabeledCard label={t("flashcard.quiz.weakTagsTitle")}>
            <StackV gap={4} items={[
                () => (
                    <StackV gap={3} principle="sibling-stack"
                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                        items={weakTags.map((tag) => () => (
                            <WeakTagRow key={tag.tag} tag={tag} href={resolveTagHref(tag) ?? genericHref} />
                        ))} />
                ),
                ...(overflowWeakTags.length > 0 ? [() => (
                    <ScrollShadow hideScrollBar className="max-h-40 overflow-y-auto">
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                            items={overflowWeakTags.map((tag) => () => (
                                <WeakTagRow key={tag.tag} tag={tag} href={resolveTagHref(tag) ?? genericHref} />
                            ))} />
                    </ScrollShadow>
                )] : []),
            ]} />
        </LabeledCard>
    )
}

/** Props for {@link RecapReadinessCallout}. */
export interface RecapReadinessCalloutProps {
    /** The readiness signal returned by `completeFlashcardQuizSession`. */
    readiness: QuizSessionReadinessData
    /** Route to the AI Mock Interview surface (only navigated to once unlocked). */
    mockInterviewHref: string
}

/**
 * Recap Zone D — the cross-link toward the AI Mock Interview (StarCi's actual
 * AI-graded, credit-costing differentiator), so a learner who finishes "Quick
 * quiz" feeling good is pointed at it instead of never hearing it exists.
 * Locked state stays visible (transparent about the threshold) rather than hiding.
 */
export const RecapReadinessCallout = ({ readiness, mockInterviewHref }: RecapReadinessCalloutProps) => {
    const t = useTranslations()
    const router = useRouter()

    if (!readiness.unlocked) {
        return (
            <Callout
                status="default"
                icon={LockIcon}
                title={t("flashcard.quiz.readinessLockedTitle")}
                description={t("flashcard.quiz.readinessLockedDescription", {
                    currentAvg: readiness.currentAvg,
                    threshold: readiness.threshold,
                })}
            />
        )
    }

    return (
        <Callout
            status="success"
            icon={MicrophoneStageIcon}
            title={t("flashcard.quiz.readinessUnlockedTitle")}
            description={t("flashcard.quiz.readinessUnlockedDescription")}
            actionLabel={t("flashcard.quiz.readinessUnlockedCta")}
            onAction={() => router.push(mockInterviewHref)}
        />
    )
}

type WeakTagRowProps = {
    tag: QuizSessionWeakTagData
    href: string
}

"use client"

import { InputSearch } from "@/components/atoms/forms"
import React, { useMemo, useState } from "react"
import { CardsIcon, ClockCounterClockwiseIcon, ClockIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Box } from "@/components/frames/Box"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"

import { StackV, StackH } from "@/components/frames/Stack"
import type { QueryFlashcardReviewHistoryItem } from "@/modules/api/graphql/queries/types/my-flashcard-review-history"
import { groupByTimeBucket } from "@/modules/utils/history-buckets"

/** This component's own `data-tier`/`data-component` identity (split.md — "identity is `data-tier` + `data-component`"). */
const IDENTITY = { tier: "block", component: "FlashcardReviewHistory" } as const

/** How the run list is grouped: by deck (accordion) or by time bucket. */
export type FlashcardReviewHistoryGroupMode = "deck" | "time"

/** How many placeholder rows the co-located skeleton shows while the first page loads. */
const SKELETON_ROW_COUNT = 4

/** The completion bar reads success at/above this reviewed-ratio, else warning. */
const STRONG_COMPLETION_RATIO = 0.8

/**
 * All display text, already localized by the connected `FlashcardReviewHistory`; a story
 * passes i18n keys. A few members are FUNCTIONS rather than plain strings — `cardCount` /
 * `xp` / `deckRunCount` / `timeBucket` / `runCount` interpolate PER ROW or PER GROUP, so a
 * single resolved string (the shape every other label in this system takes) cannot carry
 * them; the connected file still owns every `t()` call, it just hands down a resolver
 * instead of a value.
 */
export interface FlashcardReviewHistoryLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    searchPlaceholder: string
    groupByDeck: string
    groupByTime: string
    filterEmpty: string
    loadMore: string
    /** Per-row "reviewed/total" caption. */
    cardCount: (reviewedCount: number, cardCount: number) => string
    /** Per-row XP chip text. */
    xp: (xpEarned: number) => string
    /** "N runs" — used both for the search result count and per-deck-group count. */
    deckRunCount: (count: number) => string
    /** Resolves a {@link TimeBucketKey} into its heading. */
    timeBucket: (key: string) => string
    /** "N runs" caption trailing a time-bucket heading. */
    runCount: (count: number) => string
}

/** Props for {@link _FlashcardReviewHistory} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewHistoryProps {
    /** Runs fetched so far (accumulated across "load more" pages), `updatedAt DESC`. */
    items: Array<QueryFlashcardReviewHistoryItem>
    /** Total run count across every page — gates the "load more" button. */
    totalCount: number
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero runs at all → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Fetches the next offset-paginated page. */
    onLoadMore: () => void
    /** True while a "load more" page is in flight — disables the load-more button. */
    isLoadingMore?: boolean
    /** Formats an ISO timestamp in the viewer's locale (medium date style) — resolved by the connected file so this stays store-free. */
    formatDate: (iso: string) => string
    /** Deep-links a run's deck into its reviewer. */
    onOpenDeck: (deckId: string) => void
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
    labels: FlashcardReviewHistoryLabels
}

/**
 * "Study cards" run history — the presentational half of {@link FlashcardReviewHistory}, composed
 * on the tier-correct vocabulary (`InputSearch` / `TabsCard` / `LabeledAccordionCard` /
 * `SurfaceCardList` / `ProgressMeter`). Three states in the fixed order
 * error → skeleton → empty → content (`loading-and-skeleton.md`): `error` falls to the shared
 * `AsyncContentError` frame, `isEmpty` (once settled) to `AsyncContentEmpty`, and otherwise the
 * ONE toolbar+list tree renders with `isSkeleton` threaded to every leaf that carries it.
 *
 * Time-bucket sections collapse `LabeledCard frameless` + list into `SurfaceCardList` (label /
 * labelEnd / subtleLabel owned by the list). Skeleton uses the same `SurfaceCardList` + data
 * `items` (no parallel skeleton tree). `TabsCard` / `LabeledAccordionCard` / `ProgressMeter`
 * carry no `isSkeleton` of their own (missingSkeletonSupport) — mirrored MINIMALLY in place
 * with `Skeleton.*`.
 *
 * @param props - {@link FlashcardReviewHistoryProps}
 */
export const _FlashcardReviewHistory = ({
    items,
    totalCount,
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onLoadMore,
    isLoadingMore = false,
    formatDate,
    onOpenDeck,
    onStartReview,
    labels,
}: FlashcardReviewHistoryProps) => {
    const [query, setQuery] = useState("")
    const [groupMode, setGroupMode] = useState<FlashcardReviewHistoryGroupMode>("deck")

    // search filters the loaded runs by deck title (client-side over already-fetched
    // items — no BE change; the deck title is already in the response).
    const searchedItems = useMemo(() => {
        const needle = query.trim().toLowerCase()
        if (!needle) {
            return items
        }
        return items.filter((item) => item.deckTitle.toLowerCase().includes(needle))
    }, [items, query])

    // group runs by deck — the same deck reviewed multiple times otherwise scatters
    // across the flat timeline. `items` is already `updatedAt DESC` and `Map` preserves
    // first-seen order, so a group's position = its MOST RECENT run — no re-sort needed.
    const groupedByDeck = useMemo(() => {
        const groups = new Map<string, { deckId: string, deckTitle: string, items: Array<QueryFlashcardReviewHistoryItem> }>()
        for (const item of searchedItems) {
            const existing = groups.get(item.deckId)
            if (existing) {
                existing.items.push(item)
            } else {
                groups.set(item.deckId, { deckId: item.deckId, deckTitle: item.deckTitle, items: [item] })
            }
        }
        return Array.from(groups.values())
    }, [searchedItems])

    const timeBuckets = useMemo(
        () => groupByTimeBucket(searchedItems, (item) => item.updatedAt),
        [searchedItems],
    )

    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1).
    if (error) {
        return <AsyncContentError identity={IDENTITY} title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={IDENTITY}
                icon={ClockCounterClockwiseIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartReview ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartReview} />
                ) : undefined}
            />
        )
    }

    /** Shared row body — `showDeck` puts the deck title on the primary line (time
     *  grouping, where the deck isn't the group header), else the date leads. */
    const runRow = (item: QueryFlashcardReviewHistoryItem, showDeck: boolean) => {
        const ratio = item.cardCount > 0 ? item.reviewedCount / item.cardCount : 0
        const cardCountLabel = labels.cardCount(item.reviewedCount, item.cardCount)
        return (
            <StackH gap={3} items={[
                () => (
                    <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                        () => <Typography size="sm" truncate text={showDeck ? item.deckTitle : formatDate(item.updatedAt)} />,
                        () => <Typography size="xs" color="muted" truncate text={showDeck ? `${formatDate(item.updatedAt)} · ${cardCountLabel}` : cardCountLabel} />,
                        () => (
                            <Box className="max-w-[220px]">
                                <ProgressMeter
                                    value={item.reviewedCount}
                                    max={Math.max(item.cardCount, 1)}
                                    color={ratio >= STRONG_COMPLETION_RATIO ? "success" : "warning"}
                                />
                            </Box>
                        ),
                    ]} />
                ),
                ...(item.xpEarned > 0 ? [() => (
                    <Chip tone="warning" text={labels.xp(item.xpEarned)} classNames={["shrink-0"]} />
                )] : []),
            ]} />
        )
    }

    // Toolbar: search decks (left) + run count and grouping toggle (right). `TabsCard`
    // carries no `isSkeleton` of its own — its loading state mirrors it inline with a bare
    // `Skeleton`, right where it sits (missingSkeletonSupport), instead of a parallel tree.
    const toolbar = (
        <StackH gap={4} principle="content-row" justify="between" at="sm"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (
                    <Box className="w-full">
                        <InputSearch
                            isSkeleton={isSkeleton}
                            ariaLabel={labels.searchPlaceholder}
                            placeholder={labels.searchPlaceholder}
                            value={query}
                            onValueChange={setQuery}
                        />
                    </Box>
                ),
                () => (
                    <StackH gap={3} classNames={["shrink-0"]} items={[
                        () => <Typography size="sm" color="muted" isSkeleton={isSkeleton} text={labels.deckRunCount(searchedItems.length)} />,
                        () => (isSkeleton ? (
                            <Skeleton className="h-9 w-16 rounded-medium" />
                        ) : (
                            <TabsCard
                                variant="primary"
                                leftTabs={{
                                    selectedKey: groupMode,
                                    ariaLabel: labels.groupByDeck,
                                    onSelectionChange: (key) => setGroupMode(String(key) as FlashcardReviewHistoryGroupMode),
                                    items: [
                                        {
                                            key: "deck",
                                            label: <CardsIcon className="size-5" aria-label={labels.groupByDeck} focusable="false" />,
                                        },
                                        {
                                            key: "time",
                                            label: <ClockIcon className="size-5" aria-label={labels.groupByTime} focusable="false" />,
                                        },
                                    ],
                                }}
                            />
                        )),
                    ]} />
                ),
            ]} />
    )

    // Flat placeholder rows — loading shape regardless of `groupMode` (grouped shape unknown
    // yet). Same `SurfaceCardList` + data `items` as the live time buckets; free-form `content`
    // carries the shimmer (List free-form does not auto-forward `isSkeleton` into slots).
    const skeletonItems: Array<SurfaceCardListItem> = Array.from(
        { length: SKELETON_ROW_COUNT },
        (_unused, index) => ({
            key: `skeleton-${index}`,
            content: () => (
                <StackH gap={3} items={[
                    () => (
                        <StackV gap={1} classNames={["min-w-0", "flex-1"]} items={[
                            () => <Skeleton.Typography type="body-sm" width="1/2" />,
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => <Skeleton.ProgressBar className="max-w-[220px]" />,
                        ]} />
                    ),
                    () => <Skeleton className="h-6 w-12 shrink-0 rounded-full" />,
                ]} />
            ),
        }),
    )

    const body = isSkeleton ? (
        <SurfaceCardList isSkeleton items={skeletonItems} />
    ) : searchedItems.length === 0 ? (
        <SurfaceCard body={() => <Typography size="sm" color="muted" align="center" text={labels.filterEmpty} />} />
    ) : groupMode === "deck" ? (
        // group=deck — NO `label` (the toolbar's group toggle is the heading); "N runs"
        // rides in the header via `titleEnd`, panel = that deck's runs.
        <LabeledAccordionCard
            items={groupedByDeck.map((group) => ({
                id: group.deckId,
                title: group.deckTitle,
                titleEnd: () => (
                    <Typography size="xs" color="muted" classNames={["shrink-0"]} text={labels.deckRunCount(group.items.length)} />
                ),
                body: () => (
                    <StackV gap={1} items={group.items.map((item) => () => (
                        <Box key={item.id} principle="control-pad" className="rounded-lg px-3 py-2 text-left transition-colors hover:bg-default"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <button
                                type="button"
                                onClick={() => onOpenDeck(item.deckId)}
                                className="w-full text-left"
                            >
                                {runRow(item, false)}
                            </button>
                        </Box>
                    ))} />
                ),
            }))}
        />
    ) : (
        // group=time — each non-empty bucket is a `SurfaceCardList` owning subtleLabel +
        // labelEnd (B37: no LabeledCard frameless shell around a list surface).
        <StackV gap={3} items={timeBuckets.map((bucket) => () => (
            <SurfaceCardList
                key={bucket.key}
                subtleLabel
                label={labels.timeBucket(bucket.key)}
                labelEnd={labels.runCount(bucket.items.length)}
                items={bucket.items.map((item) => ({
                    key: item.id,
                    onPress: () => onOpenDeck(item.deckId),
                    content: () => runRow(item, true),
                }))}
            />
        ))} />
    )

    const showLoadMore = !isSkeleton && items.length < totalCount

    return (
        <StackV gap={3} identity={IDENTITY} items={[
            () => toolbar,
            () => body,
            ...(showLoadMore ? [() => (
                <Button
                    variant="secondary"
                    size="sm"
                    classNames={["self-center"]}
                    isDisabled={isLoadingMore}
                    onPress={onLoadMore}
                    label={labels.loadMore}
                />
            )] : []),
        ]} />
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { ArrowRightIcon, ChartLineUpIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { VerdictHeroCard, type VerdictHeroBand } from "@/components/blocks/stats/VerdictHeroCard"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Retention band BY VALUE — drives `VerdictHeroCard`'s color + every retention chip here. */
export const retentionColorOf = (percent: number): VerdictHeroBand =>
    percent < 50 ? "danger" : percent < 75 ? "warning" : "success"

/** Below this many lifetime reviews the aggregates are noise — mirrors
 *  `FlashcardStatsStrip`'s own `RETENTION_MIN_REVIEWS` gate constant. */
export const RETENTION_MIN_REVIEWS = 5

/** Healthy-memory retention mark the hero meter aims at (`stats-insight-redesign`
 *  proposal — FE-side constant; the BE intentionally has no such column). */
export const RETENTION_TARGET = 85

/** How many placeholder rows the co-located skeleton shows for the weak-topics list. */
const WEAK_TOPIC_SKELETON_ROW_COUNT = 4

/** One worst-first weak topic — chip text already resolved (interpolated) by the connected half. */
export interface FlashcardReviewWeakTag {
    /** Topic/tag name. */
    tag: string
    /** Retention percentage for this tag. */
    retention: number
    /** Already-translated `"{retention}% recall"` chip text. */
    chipLabel: string
}

/** All display text, already localized by the connected `FlashcardReviewStats`; a story passes i18n keys. */
export interface FlashcardReviewStatsLabels {
    errorTitle: string
    retry: string
    emptyTitle: string
    emptyDescription: string
    emptyAction: string
    memoryHealthLabel: string
    /** Rich verdict sentence (embeds a `<b>`) — already picked BY BAND and resolved. */
    verdict: ReactNode
    /** Evidence caption under the verdict — already interpolated (retention/target). */
    sub: string
    /** CTA label — already picked BY BAND ("ease off new cards" vs "review weakest deck"). */
    cta: string
    /** "Well-learned cards (mature)" + its caption, already joined with a line break. */
    matureSplitLabel: ComponentType
    /** "New cards (young)" + its caption, already joined with a line break. */
    youngSplitLabel: ComponentType
    weakTopicMapLabel: string
    studyHeading: string
}

/** Props for {@link _FlashcardReviewStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardReviewStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with fewer than `RETENTION_MIN_REVIEWS` lifetime reviews → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Jumps the overview tab strip back to the study overview (empty-state action). */
    onStartReview?: () => void
    /** Course-scoped lifetime retention — the hero card's headline value. */
    retentionRate?: number
    matureRetention?: number
    youngRetention?: number
    /** Every attempted tag, already ranked worst-first, chip text pre-resolved. */
    weakTags?: Array<FlashcardReviewWeakTag>
    /** Deck to drill from a CTA — the lowest-retention deck, else the top leech card's own deck. */
    weakestDeckId?: string | null
    /** Already-resolved "Review \"{tag}\" (weakest)" CTA — `undefined` hides the button (no deck to drill). */
    weakTopicDrillCta?: string
    /** Already-resolved "Overall average is …" caption — `undefined` hides the caption. */
    weakTopicAvgCaption?: string
    /** Opens a deck's reviewer — the single onward action every row/CTA here shares. */
    onOpenDeck: (deckId: string) => void
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — omitted (as in a story) → the self-fetching study zone is skipped. */
    displayId?: string
    labels: FlashcardReviewStatsLabels
}

/**
 * "Study Cards" aggregate stats — the presentational half of {@link FlashcardReviewStats},
 * insight-first (verdict → evidence → action, `stats-canonical-fold`): (1) memory-health hero
 * (mature/young split vs target), (2) full weak-topic map worst-first, (3) passive RAG study
 * suggestions. Four states in the fixed order error → loading → empty → content: `error` falls
 * to the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, and otherwise the
 * tree renders with `isSkeleton` threaded to every leaf that supports it
 * (loading-and-skeleton.md). `VerdictHeroCard`/`SectionCard` carry no `isSkeleton` of their
 * own — the hero zone swaps to a hand-mirrored `Skeleton.*` tree in the SAME position while
 * shimmering (its headline `value` is a plain number, not a slot a shimmer can sit in); the
 * weak-topic map is a `SurfaceCardList` with data `items` + `isSkeleton` (B37 class A collapse
 * of `LabeledCard frameless` + list). See `tiers/split.md` — the connected `index.tsx` owns
 * the fetch, the band decision, and i18n.
 *
 * @param props - {@link FlashcardReviewStatsProps}
 */
export const _FlashcardReviewStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onStartReview,
    retentionRate = 0,
    matureRetention = 0,
    youngRetention = 0,
    weakTags = [],
    weakestDeckId = null,
    weakTopicDrillCta,
    weakTopicAvgCaption,
    onOpenDeck,
    courseId,
    displayId,
    labels,
}: FlashcardReviewStatsProps) => {
    // error → skeleton → empty → content (BLOCK-8): error beats a stale loading flag; the empty
    // and error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (§6).
    if (error) {
        return (
            <AsyncContentError
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                title={labels.errorTitle}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />
        )
    }
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={{ tier: "page", component: "FlashcardReviewStats" }}
                icon={ChartLineUpIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={onStartReview ? () => (
                    <Button label={labels.emptyAction} variant="secondary" size="sm" onPress={onStartReview} />
                ) : undefined}
            />
        )
    }

    // band drives VerdictHeroCard's color coding — computed presentationally from the same
    // value the connected half already used (via the same pure function) to pick its text keys.
    const band = retentionColorOf(retentionRate)

    // ZONE 2 rows — fixed title + Chip meta; skeleton keeps the SAME list shape via
    // `SurfaceCardList isSkeleton` (title shimmers; meta Chip owns its own resting state).
    const gapItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: WEAK_TOPIC_SKELETON_ROW_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            title: "Topic",
            meta: () => <Chip isSkeleton />,
        }))
        : weakTags.map((tagStat) => ({
            key: tagStat.tag,
            title: tagStat.tag,
            meta: () => <Chip tone={retentionColorOf(tagStat.retention)} text={tagStat.chipLabel} />,
        }))
    const showGap = isSkeleton || gapItems.length > 0
    // action row (drill CTA + avg caption) shows while shimmering (placeholder) or once either
    // resolved string is present.
    const showActionRow = isSkeleton || Boolean(weakTopicDrillCta) || Boolean(weakTopicAvgCaption)

    return (
        <StackV identity={{ tier: "page", component: "FlashcardReviewStats" }} gap={6} items={[
            // ZONE 1 — "Memory health" hero (◎ vs target). `VerdictHeroCard` has no `isSkeleton`
            // of its own — while shimmering this swaps to a hand-mirrored `Skeleton.*` tree in
            // the exact same position instead (missingSkeletonSupport).
            () => (
                <LabeledCard label={labels.memoryHealthLabel} frameless>
                    {isSkeleton ? (
                        <SectionCard>
                            <StackV gap={4} principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                items={[
                                    () => (
                                        <StackH gap={3} principle="value-row" align="baseline"
                                            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                            items={[
                                                () => <Skeleton className="h-9 w-20 rounded" />,
                                                () => <Skeleton className="h-[14px] w-6 rounded" />,
                                            ]} />
                                    ),
                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                    () => <Skeleton.ProgressBar />,
                                    () => (
                                        <Box className="overflow-hidden rounded-2xl border border-default">
                                            <StackH gap={1} principle="name-handle" align="stretch" divider
                                                explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                items={[
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                    () => (
                                                        <Box principle="card-padding" className="flex-1 p-4"
                                                            explain="Card body inset — not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                            <StackV gap={2} principle="title-subtitle"
                                                                explain="Title over supporting line — not label-field, because neither line is a form control label."
                                                                items={[
                                                                    () => <Skeleton.Typography type="body-xs" width="2/3" />,
                                                                    () => <Skeleton className="h-5 w-14 rounded" />,
                                                                ]} />
                                                        </Box>
                                                    ),
                                                ]} />
                                        </Box>
                                    ),
                                    () => <Skeleton.Button width="w-40" />,
                                ]} />
                        </SectionCard>
                    ) : (
                        <VerdictHeroCard
                            value={retentionRate}
                            unit="%"
                            band={band}
                            verdict={labels.verdict}
                            sub={labels.sub}
                            meter={{ value: retentionRate, max: 100, target: RETENTION_TARGET }}
                            splits={[
                                {
                                    label: labels.matureSplitLabel,
                                    value: `${matureRetention}%`,
                                    band: retentionColorOf(matureRetention),
                                },
                                {
                                    label: labels.youngSplitLabel,
                                    value: `${youngRetention}%`,
                                    band: retentionColorOf(youngRetention),
                                },
                            ]}
                            action={weakestDeckId ? () => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={labels.cta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                />
                            ) : undefined}
                        />
                    )}
                </LabeledCard>
            ),

            // ZONE 2 — "Weak points by topic" (▽ split by tag, → drill CTA). FULL worst-first
            // list via `SurfaceCardList` (owns label). Drill CTA + avg caption live OUTSIDE the
            // card (buttons never inside a list card).
            ...(showGap ? [() => (
                <StackV gap={4} items={[
                    () => (
                        <SurfaceCardList
                            label={labels.weakTopicMapLabel}
                            isSkeleton={isSkeleton}
                            items={gapItems}
                        />
                    ),
                    ...(showActionRow ? [() => (
                        <StackV gap={3} items={[
                            ...(isSkeleton ? [() => (
                                <Skeleton.Button width="w-44" className="self-start" />
                            )] : weakTopicDrillCta && weakestDeckId ? [() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    suffixIcon={ArrowRightIcon}
                                    label={weakTopicDrillCta}
                                    onPress={() => onOpenDeck(weakestDeckId)}
                                    classNames={["self-start"]}
                                />
                            )] : []),
                            ...(isSkeleton ? [() => (
                                <Skeleton.Typography type="body-xs" width="2/3" />
                            )] : weakTopicAvgCaption ? [() => (
                                <Typography size="xs" color="muted" text={weakTopicAvgCaption} />
                            )] : []),
                        ]} />
                    )] : []),
                ]} />
            )] : []),

            // ZONE 3 — passive RAG "Study suggestions": weak tags → course-wide content search
            // (self-hiding when there's nothing weak / no match). Needs the slug for result
            // deep links, so it waits on `displayId`; hidden while shimmering (it fetches its
            // own state).
            ...(!isSkeleton && displayId ? [() => (
                <RelatedContentList
                    courseId={courseId}
                    courseDisplayId={displayId}
                    query={weakTags.map((tagStat) => tagStat.tag).join(" ")}
                    label={labels.studyHeading}
                />
            )] : []),
        ]} />
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Container } from "@/components/frames/Container"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * Loading placeholder for the flashcard reviewer. Mirrors the real shape
 * top-to-bottom: the edge-to-edge {@link import("@/components/blocks/navigation/WorkSessionHeader").WorkSessionHeader}
 * band (back-link · deck identity · counter · progress-segment bar), then a
 * `max-w-3xl` centered body — level/tag chips, the {@link import("@/components/blocks/cards/FlipCard").FlipCard}
 * face (label + two prompt lines), and the prev/show-answer controls. (Was wrong:
 * a thin progress bar instead of the header band, so the band popped in on resolve.)
 */
export const FlashcardReviewerSkeleton = ({ className }: WithClassNames<undefined> = {}) => {
    return (
        <div className={className}>
            <StackV
                gap={6}
                items={[
                    () => (
                        <div className="border-b border-default bg-surface">
                            <StackH
                                gap={1}
                                padding={{ base: { x: 5, y: 3 }, sm: { x: 6, y: 3 } }}
                                principle="pill-pad"
                                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control."
                                items={[
                                    () => (
                                        <StackH
                                            gap={4}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center"
                                            items={[
                                                () => <Skeleton className="h-4 w-16 rounded" />,
                                                () => (
                                                    <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                                                ),
                                                () => <Skeleton className="hidden h-4 w-24 rounded @app-sm:block" />,
                                                () => (
                                                    <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                                                ),
                                                () => <Skeleton className="h-4 w-20 rounded" />,
                                            ]}
                                        />
                                    ),
                                ]}
                            />
                            <Box principle="pill-pad" className="px-4 pb-2 @app-sm:px-6"
                                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                                <StackH
                                    gap={2}
                                    classNames={["w-full"]}
                                    items={Array.from({ length: 6 }, (_unused, index) => () => (
                                        <Skeleton key={index} className="h-1 flex-1 rounded-full" />
                                    ))}
                                />
                            </Box>
                        </div>
                    ),
                    () => (
                        <Container
                            size="md"
                            padding={1}
                            body={() => (
                                <StackV
                                    gap={6}
                                    items={[
                                        () => (
                                            <Cluster
                                                gap={3}
                                                principle="chip-row"
                                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                                align="center"
                                                items={[
                                                    () => <Skeleton.Chip />,
                                                    () => <Skeleton.Chip />,
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackV
                                                gap={4}
                                                principle="label-field"
                                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                                items={[
                                                    () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                                    () => (
                                                        <SurfaceCard
                                                            padding={6}
                                                            body={() => (
                                                                <StackV
                                                                    gap={4}
                                                                    principle="sibling-stack"
                                                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                                                    items={[
                                                                        () => <Skeleton.Typography type="body" width="3/4" />,
                                                                        () => <Skeleton.Typography type="body" width="2/3" />,
                                                                    ]}
                                                                />
                                                            )}
                                                        />
                                                    ),
                                                ]}
                                            />
                                        ),
                                        () => (
                                            <StackH
                                                gap={4}
                                                principle="flex-action"
                                                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                justify="between"
                                                align="center"
                                                items={[
                                                    () => <Skeleton.Button />,
                                                    () => <Skeleton.Button />,
                                                ]}
                                            />
                                        ),
                                    ]}
                                />
                            )}
                        />
                    ),
                ]}
            />
        </div>
    )
}

"use client"

import React, { useState } from "react"
import { Button, Chip, Label, Spinner, Typography } from "@heroui/react"
import { CaretLeftIcon, CaretRightIcon, LockIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { WorkSessionHeader } from "@/components/blocks/navigation/WorkSessionHeader"
import { ConfirmDialog } from "@/components/composites/feedback/ConfirmDialog"
import { FlipCard } from "@/components/blocks/cards/FlipCard"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { LEVEL_COLOR } from "@/modules/utils/flashcards"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { type FlashcardCardEntity } from "@/modules/types/entities/flashcard-card"

/** How many segments the header's progress meter mirrors while shimmering. */
const HEADER_SKELETON_SEGMENT_COUNT = 6

/** How many placeholder chips the level/tag row mirrors while shimmering. */
const SKELETON_CHIP_COUNT = 2

/** Every translated string {@link _FlashcardReviewer} needs — resolved by the connected `FlashcardReviewer`. */
export interface FlashcardReviewerLabels {
    /** `WorkSessionHeader`'s back-link label, both branches. */
    exit: string
    /** `WorkSessionHeader`'s mode title, both branches. */
    title: string
    /** Already-interpolated "card N/total" — the connected file resolves the pair per `done`. */
    counter: string
    /** Under the spinner in the transient "saving" hand-off (`done` branch). */
    savingLabel: string
    leaveTitle: string
    finishEarlyTitle: string
    leaveConfirm: string
    finishEarlyConfirm: string
    leaveCta: string
    finishEarlyCta: string
    stayIn: string
    questionLabel: string
    answerLabel: string
    premiumLockedTitle: string
    premiumLockedHint: string
    noAnswer: string
    premiumCta: string
    rateHint: string
    rateAria: string
    showAnswer: string
    previous: string
    next: string
    finishEarly: string
    /** Shared by both the empty and the error branch (mirrors the original, which used one key for both). */
    emptyTitle: string
}

/** Props for {@link _FlashcardReviewer} — presentational; every value already resolved by `index.tsx`. */
export interface FlashcardReviewerProps extends WithClassNames<undefined> {
    /** First load, nothing in hand yet (deck query + session resolve both settled) — the whole tree shimmers in place. */
    isSkeleton?: boolean
    /** Settled, sessioned, and the resolved card list is empty. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). */
    error?: unknown
    /** Retries the deck query. */
    onRetry?: () => void
    /** Every translated string this tree draws. */
    labels: FlashcardReviewerLabels

    /** Deck title, once the deck query resolves. */
    deckTitle?: string
    /**
     * Past the last card (or explicitly finished) — the transient "saving" hand-off
     * before the completion mutation resolves and the caller navigates to the result route.
     */
    done: boolean

    /** 0-indexed position of the card currently shown. */
    currentIndex: number
    /** Total cards in this review run. */
    totalCards: number
    /** The card currently shown; absent only transiently (e.g. `done`). */
    card?: FlashcardCardEntity
    /** Translated label for `card.level`, resolved by the connected file (dynamic i18n key). */
    cardLevelLabel?: string
    /** A premium card withheld from a non-enrolled viewer. */
    isLocked: boolean
    isFirst: boolean
    isLast: boolean
    /** Whether the answer side is currently shown. */
    revealed: boolean
    /** True while a grade mutation is in flight — disables the rating bar. */
    reviewing: boolean
    /** Positions already graded (order-independent) — drives the header's per-segment green. */
    gradedIndexes: ReadonlyArray<number>
    /** SM-2 grade options, already localized with their next-interval preview. */
    ratingOptions: Array<RatingOption>

    /** Returns to the study overview. */
    onBack?: () => void
    /** Reveals the answer side of the current card. */
    onReveal: () => void
    /** Grades the current card and advances. */
    onRate: (grade: number) => void
    onPrev: () => void
    onNext: () => void
    /** Free-navigation: jump straight to any step from the progress-segment bar. */
    onSegmentClick: (position: number) => void
    /** Ends the run now (past the confirm dialog). */
    onFinishEarly: () => void
    /** Opens the course page so the viewer can enrol to unlock premium cards. */
    onUnlock: () => void
}

/**
 * Spaced-repetition reviewer over one deck — the presentational half of
 * {@link import("./index").FlashcardReviewer}. Four states in the fixed order
 * error → skeleton → empty → content (`loading-and-skeleton.md`): `error` falls to
 * the shared `AsyncContentError` frame, `isEmpty` to `AsyncContentEmpty`, otherwise
 * the ONE real tree renders with `isSkeleton` threaded through. None of this tree's
 * leaves (`WorkSessionHeader`, `FlipCard`, `SectionCard`, `RatingBar`, `ConfirmDialog`,
 * `MarkdownContent`) take an `isSkeleton` prop of their own, so the shimmer is mirrored
 * INLINE with `Skeleton.*` at the exact spot those leaves would otherwise sit — still
 * co-located (same wrapper, same position), not a second parallel tree. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the session-resolve
 * effects, and every i18n resolution.
 *
 * @param props - {@link FlashcardReviewerProps}
 */
export const _FlashcardReviewer = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    labels,
    deckTitle,
    done,
    currentIndex,
    totalCards,
    card,
    cardLevelLabel,
    isLocked,
    isFirst,
    isLast,
    revealed,
    reviewing,
    gradedIndexes,
    ratingOptions,
    onBack,
    onReveal,
    onRate,
    onPrev,
    onNext,
    onSegmentClick,
    onFinishEarly,
    onUnlock,
    className,
}: FlashcardReviewerProps) => {
    // "leave" (Exit) · "endEarly" (Finish early) — which confirm dialog is open, if any.
    // Pure UI toggle, not fetched/persisted data, so it lives here rather than in the
    // connected file (loading-and-skeleton.md's test: renders with no server/store/session).
    const [confirmAction, setConfirmAction] = useState<null | "leave" | "endEarly">(null)

    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md §1/§6)
    if (error) {
        return <AsyncContentError title={labels.emptyTitle} onRetry={onRetry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={labels.emptyTitle} />
    }

    const identity = deckTitle ? { name: deckTitle } : undefined

    const header = isSkeleton ? (
        <Box className="sticky top-16 z-10 border-b border-default bg-surface">
            <StackH
                gap={1}
                padding={{ base: { x: 5, y: 3 }, sm: { x: 6, y: 3 } }}
                principle="pill-pad"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control."
                items={[() => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        divider
                        classNames={["w-full"]}
                        items={[
                            () => <Skeleton className="h-4 w-16 rounded" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="hidden h-4 w-24 rounded @app-sm:block" />,
                            () => (
                                <span className="hidden h-5 w-px shrink-0 bg-default @app-sm:block" aria-hidden />
                            ),
                            () => <Skeleton className="h-4 w-20 rounded" />,
                        ]}
                    />
                )]}
            />
            <Box principle="pill-pad" className="px-4 pb-2 @app-sm:px-6"
                explain="Pill/chip inset — not control-pad, because this pads a compact badge shape rather than a form control.">
                <StackH
                    gap={2}
                    classNames={["w-full"]}
                    items={Array.from({ length: HEADER_SKELETON_SEGMENT_COUNT }, (_unused, index) => () => (
                        <Skeleton key={index} className="h-1 flex-1 rounded-full" />
                    ))}
                />
            </Box>
        </Box>
    ) : done ? (
        <WorkSessionHeader
            backLabel={labels.exit}
            onBack={onBack ?? (() => {})}
            title={labels.title}
            identity={identity}
            counter={labels.counter}
            current={totalCards}
            total={totalCards}
        />
    ) : (
        <>
            <WorkSessionHeader
                backLabel={labels.exit}
                onBack={() => setConfirmAction("leave")}
                title={labels.title}
                identity={identity}
                counter={labels.counter}
                current={currentIndex}
                total={totalCards}
                doneSet={gradedIndexes}
                onSegmentClick={onSegmentClick}
                onFinish={() => setConfirmAction("endEarly")}
                finishLabel={labels.finishEarly}
            />
            <ConfirmDialog
                isOpen={confirmAction !== null}
                onOpenChange={(open) => { if (!open) { setConfirmAction(null) } }}
                title={confirmAction === "leave" ? labels.leaveTitle : labels.finishEarlyTitle}
                description={confirmAction === "leave" ? labels.leaveConfirm : labels.finishEarlyConfirm}
                confirmLabel={confirmAction === "leave" ? labels.leaveCta : labels.finishEarlyCta}
                cancelLabel={labels.stayIn}
                onConfirm={() => {
                    const action = confirmAction
                    setConfirmAction(null)
                    if (action === "leave") {
                        onBack?.()
                    } else if (action === "endEarly") {
                        onFinishEarly()
                    }
                }}
            />
        </>
    )

    const cardLevel = card?.level ?? null
    const chipItems = isSkeleton
        ? Array.from({ length: SKELETON_CHIP_COUNT }, () => () => <Skeleton.Chip />)
        : card && (cardLevel || (card.tags?.length ?? 0) > 0)
            ? [
                ...(cardLevel ? [() => (
                    <Chip size="sm" variant="soft" color={LEVEL_COLOR[cardLevel] ?? "default"}>
                        {cardLevelLabel}
                    </Chip>
                )] : []),
                ...(card.tags ?? []).map((tag) => () => (
                    <Chip key={tag} size="sm" variant="soft" color="default">
                        {tag}
                    </Chip>
                )),
            ]
            : []

    const body = isSkeleton ? (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => <Cluster gap={3} principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center" items={chipItems} />,
                () => (
                    <StackV gap={4} principle="label-field"
                        explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                        items={[
                            () => <Skeleton.Typography type="body-xs" width="1/4" />,
                            () => (
                                <SurfaceCard padding={6} body={() => (
                                    <StackV gap={4} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Skeleton.Typography type="body" width="3/4" />,
                                            () => <Skeleton.Typography type="body" width="2/3" />,
                                        ]} />
                                )} />
                            ),
                        ]} />
                ),
                () => (
                    <StackH gap={4} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        justify="between" align="center" items={[
                            () => <Skeleton.Button />,
                            () => <Skeleton.Button />,
                        ]} />
                ),
            ]} />
        )} />
    ) : done ? (
        <Container size="md" padding={1} body={() => (
            <Box className="py-10">
                <StackV gap={4} align="center" principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    classNames={["w-full"]} items={[
                        () => <Spinner size="lg" />,
                        () => (
                            <Typography type="body-sm" color="muted">
                                {labels.savingLabel}
                            </Typography>
                        ),
                    ]} />
            </Box>
        )} />
    ) : (
        <Container size="md" padding={1} body={() => (
            <StackV gap={6} items={[
                () => (
                    <FlipCard
                        revealed={revealed}
                        questionLabel={labels.questionLabel}
                        answerLabel={labels.answerLabel}
                        front={() => <MarkdownContent plain markdown={card?.question ?? ""} />}
                        belowFront={chipItems.length > 0 ? () => (
                            <Cluster gap={3} principle="chip-row"
                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                align="center" items={chipItems}  />
                        ) : undefined}
                        back={() => (
                            <>
                                {isLocked ? (
                                    <StackV gap={4} principle="sibling-stack"
                                        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                        align="center" classNames={["flex-1"]} items={[
                                            () => <LockIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                            () => (
                                                <Typography type="body-sm" weight="semibold">
                                                    {labels.premiumLockedTitle}
                                                </Typography>
                                            ),
                                            () => (
                                                <Typography type="body-xs" color="muted">
                                                    {labels.premiumLockedHint}
                                                </Typography>
                                            ),
                                        ]} />
                                ) : (
                                    <>
                                        {card?.answer ? (
                                            <MarkdownContent plain markdown={card.answer} arcSections />
                                        ) : (
                                            <Typography type="body-sm" color="muted">
                                                {labels.noAnswer}
                                            </Typography>
                                        )}
                                        {card?.explanation ? (
                                            <MarkdownContent plain markdown={card.explanation} />
                                        ) : null}
                                    </>
                                )}
                            </>
                        )}
                    />
                ),
                ...(revealed && isLocked ? [() => (
                    <StackH gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        justify="center" items={[() => (
                            <Button size="sm" variant="primary" onPress={onUnlock}>
                                {labels.premiumCta}
                            </Button>
                        )]} />
                )] : revealed ? [() => (
                    <SectionCard withVerdict={{ enable: true, variant: "accent" }}>
                        <Label>{labels.rateHint}</Label>
                        <RatingBar
                            options={ratingOptions}
                            onRate={onRate}
                            ariaLabel={labels.rateAria}
                            isPending={reviewing}
                        />
                    </SectionCard>
                )] : [() => (
                    <Cluster gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        align="center" items={[
                            () => (
                                <Button size="sm" variant="primary" className="w-full @app-sm:w-auto" onPress={onReveal}>
                                    {labels.showAnswer}
                                </Button>
                            ),
                            () => (
                                <Button
                                    size="sm"
                                    variant="secondary"
                                    isIconOnly
                                    isDisabled={isFirst}
                                    aria-label={labels.previous}
                                    onPress={onPrev}
                                >
                                    <CaretLeftIcon weight="bold" className="size-4" aria-hidden focusable="false" />
                                </Button>
                            ),
                            () => (
                                <Button
                                    size="sm"
                                    variant="secondary"
                                    isIconOnly
                                    isDisabled={isLast}
                                    aria-label={labels.next}
                                    onPress={onNext}
                                >
                                    <CaretRightIcon weight="bold" className="size-4" aria-hidden focusable="false" />
                                </Button>
                            ),
                        ]} />
                )]),
            ]} />
        )} />
    )

    const bodyShell = (
        <Box principle="page-pad" className="px-4 pb-6 pt-10 @app-sm:px-6"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
        >{body}</Box>
    )

    return (
        <Box className={className}>
            <StackV
                gap={1}
                identity={{ tier: "block", component: "FlashcardReviewer" }}
                items={[
                    () => header,
                    () => bodyShell,
                ]}
            />
        </Box>
    )
}

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { SurfaceCardList } from "@/components/composites/cards/SurfaceCard"
import { Container } from "@/components/frames/Container"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Loading placeholder for {@link import("./index").FlashcardSessionStats} — mirrors its
 * REAL layout tree: HERO `SectionCard` holds ONLY the 4 grade-distribution rows
 * (label · meter · count) + a rollup line (its title/subtitle live in the PageHeader
 * OUTSIDE this AsyncContent), then the metric tiles (`Skeleton.Metric` grid) and the
 * weak-tags `SurfaceCardList`, so the surface never collapses or jumps when the stats
 * query resolves. Used on the revisit-by-URL path (skeleton → stats). Parallel twin held
 * for full collapse into the live `isSkeleton` path (live component outside this agent’s owns).
 */
export const FlashcardSessionStatsSkeleton = () => {
    return (
        <Container
            size="md"
            padding={1}
            body={() => (
                <StackV
                    gap={6}
                    items={[
                        () => (
                            <SectionCard contentGap={5}>
                                <StackV
                                    gap={4}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        ...Array.from({ length: 4 }, (_unused, index) => () => (
                                            <StackH
                                                key={index}
                                                gap={4}
                                                principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center"
                                                items={[
                                                    () => <Skeleton className="h-[14px] w-16 shrink-0 rounded" />,
                                                    () => <Skeleton.ProgressBar className="flex-1" />,
                                                    () => <Skeleton className="h-[14px] w-16 shrink-0 rounded" />,
                                                ]}
                                            />
                                        )),
                                        () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                    ]}
                                />
                            </SectionCard>
                        ),
                        () => (
                            <StackV
                                as="section"
                                gap={4}
                                principle="label-field"
                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                items={[
                                    () => <Skeleton className="h-[14px] w-28 rounded" />,
                                    () => (
                                        // teacher-hold: flashcards-remain-session-stats-metric-grid-gap4-no-token —
                                        // four metric tiles at preserved step 4; no card-grid token.
                                        <Grid
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            columns={{ base: 2, md: 4 }}
                                            items={Array.from({ length: 4 }).map((_unused, index) => ({
                                                key: `metric-${index}`,
                                                content: () => <Skeleton.Metric />,
                                            }))}
                                        />
                                    ),
                                ]}
                            />
                        ),
                        () => (
                            <StackV
                                as="section"
                                gap={4}
                                principle="label-field"
                                explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                                items={[
                                    () => <Skeleton className="h-[14px] w-40 rounded" />,
                                    () => (
                                        <SurfaceCardList
                                            isSkeleton
                                            items={Array.from({ length: 3 }, (_unused, index) => ({
                                                key: `pending-${index}`,
                                                content: () => (
                                                    <StackH
                                                        gap={4}
                                                        principle="content-row"
                                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                        justify="between"
                                                        align="center"
                                                        items={[
                                                            () => (
                                                                <StackH
                                                                    gap={3}
                                                                    principle="identity"
                                                                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                                                                    align="center"
                                                                    classNames={["min-w-0", "flex-1"]}
                                                                    items={[
                                                                        () => <Skeleton className="size-4 shrink-0 rounded" />,
                                                                        () => (
                                                                            <Skeleton.Typography
                                                                                type="body-sm"
                                                                                width="1/2"
                                                                                className="min-w-0 flex-1"
                                                                            />
                                                                        ),
                                                                    ]}
                                                                />
                                                            ),
                                                            () => <Skeleton className="h-5 w-16 shrink-0 rounded-full" />,
                                                        ]}
                                                    />
                                                ),
                                            }))}
                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import type { ReactNode } from "react"
import { CheckCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Section } from "@/components/composites/layout/Section"
import { MetricCard } from "@/components/composites/stats/MetricCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { Container } from "@/components/frames/Container"
import type { SkeletonProps } from "@/components/frames/_slot"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { RelatedContentList } from "@/components/blocks/learn/RelatedContentList"

/** How many placeholder rows the co-located skeleton shows for the weak-tags list. */
const SKELETON_WEAK_TAG_COUNT = 3

/**
 * One SM-2 grade bucket in the HERO distribution: its data key, i18n label key, and the
 * semantic meter tone (a low-recall grade must READ low; `good`/`easy` both share the
 * success tone). Kept here (not the connected file) because ORDER + TONE is a display
 * decision — only the label/count STRINGS need `t()`, resolved by the connected
 * `FlashcardSessionStats` (`tiers/split.md`).
 */
export const GRADE_ROW_DEFS = [
    { key: "again", labelKey: "flashcard.review.again", color: "danger" },
    { key: "hard", labelKey: "flashcard.review.hard", color: "warning" },
    { key: "good", labelKey: "flashcard.review.good", color: "success" },
    { key: "easy", labelKey: "flashcard.review.easy", color: "success" },
] as const

/** One resolved HERO grade row — label/count-percent already translated by the connected file. */
export interface FlashcardSessionStatsGradeRow {
    /** The SM-2 grade this row reports. */
    key: string
    /** Meter tone — a low-recall grade must read low. */
    color: "accent" | "success" | "warning" | "danger"
    /** Already-translated grade name ("Again", "Hard", …). */
    label: string
    /** Raw count — the meters' shared `max` is {@link FlashcardSessionStatsProps.gradeTotal}. */
    count: number
    /** Already-translated "N (P%)" readout. */
    countPercentLabel: string
}

/** One resolved "most forgotten" tag row. */
export interface FlashcardSessionStatsWeakTag {
    /** The tag text itself (not translated — content, not UI copy). */
    tag: string
    /** Already-translated "forgotten N times" readout. */
    forgotLabel: string
}

/** All display text, already localized by the connected `FlashcardSessionStats`; a story passes i18n keys. */
export interface FlashcardSessionStatsLabels {
    backLabel: string
    headerTitle: string
    headerDescription: string
    errorTitle: string
    retryLabel: string
    emptyTitle: string
    emptyDescription: string
    backToReviewLabel: string
    rollupLabel: string
    metricsLabel: string
    metricTotalLabel: string
    metricDurationLabel: string
    metricNextDueLabel: string
    metricXpLabel: string
    weakTagsHeading: string
    studyHeading: string
}

/** Props for {@link _FlashcardSessionStats} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardSessionStatsProps {
    /** First load, nothing in hand → the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no honest per-grade breakdown (not found, or a legacy count-only session) → the fallback message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler — paired with `labels.retryLabel` on the error branch. */
    onRetry?: () => void
    /** Returns to the flashcards study overview — the single onward path, never a dead end. */
    onBack: () => void
    /** The 4 SM-2 grade rows, in display order, already localized. */
    gradeRows: ReadonlyArray<FlashcardSessionStatsGradeRow>
    /** Sum of every grade row's count — the meters' shared `max`. */
    gradeTotal: number
    /** Already-formatted "reviewed" metric value. */
    metricTotalValue: string
    /** Already-formatted duration metric value ("45 seconds" / "6 minutes" / "—"). */
    metricDurationValue: string
    /** Already-formatted next-due-date metric value ("—" when nothing scheduled). */
    metricNextDueValue: string
    /** Already-formatted, already-translated XP metric value. */
    metricXpValue: string
    /** Every tag the learner forgot at least once, worst-first, already localized. */
    weakTags: ReadonlyArray<FlashcardSessionStatsWeakTag>
    /** Course id for the RAG study-suggestions child. */
    courseId: string
    /** Course display id — needed to build the study list's deep links. */
    courseDisplayId: string
    /** Weak-tag terms joined into one query string, driving the RAG "study this" list. */
    relatedQuery: string
    labels: FlashcardSessionStatsLabels
}

/**
 * The end-of-session STATS surface for a "Study cards" review run (deck-review or cross-deck
 * due-review) — the presentational half of {@link FlashcardSessionStats}: the completion screen
 * AND the render for revisiting a finished session by URL. A centered column of canonical blocks —
 * HERO = the 4-grade SM-2 distribution (NOT a binary remembered/forgot ring), then session metric
 * tiles, the most-forgotten tags, and a self-hiding RAG "study this" list keyed off those weak tags.
 *
 * Four states in the fixed order error → loading → empty → content (`loading-and-skeleton.md`):
 * `error` falls to the shared `AsyncContentError` frame; a settled `isEmpty` (not found, or a
 * legacy/degraded session with no per-grade data) falls to `AsyncContentEmpty` — never an error;
 * otherwise the ONE real tree renders, with `isSkeleton` threaded to every leaf so the shimmer
 * mirrors the loaded shape and cannot drift. The page header stays outside this switch — it is the
 * route's own chrome, not part of the async region. See `tiers/split.md` — the connected
 * `index.tsx` owns the fetch and every `t()` call.
 *
 * @param props - {@link FlashcardSessionStatsProps}
 */
export const _FlashcardSessionStats = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    onBack,
    gradeRows,
    gradeTotal,
    metricTotalValue,
    metricDurationValue,
    metricNextDueValue,
    metricXpValue,
    weakTags,
    courseId,
    courseDisplayId,
    relatedQuery,
    labels,
}: FlashcardSessionStatsProps) => {
    // reached via the "Study cards"/"Review due cards" LIVE session route AND the
    // revisit-by-URL result route — the header is the route's own chrome, unaffected
    // by the stats fetch below, so it renders unconditionally.
    const header = (
        <PageHeader
            breadcrumb={<BackLink label={labels.backLabel} onPress={onBack} />}
            title={labels.headerTitle}
            description={labels.headerDescription}
        />
    )

    let contentNode: ReactNode
    // error beats a stale loading flag; empty only once settled (BLOCK-8) — the empty and
    // error surfaces are the shared `AsyncContent*` frames, not hand-written JSX (loading-and-skeleton.md §6).
    if (error) {
        contentNode = <AsyncContentError title={labels.errorTitle} onRetry={onRetry} retryLabel={labels.retryLabel} />
    } else if (!isSkeleton && isEmpty) {
        contentNode = (
            <AsyncContentEmpty
                icon={CheckCircleIcon}
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                action={() => <Button label={labels.backToReviewLabel} variant="secondary" size="sm" onPress={onBack} />}
            />
        )
    } else {
        // most-forgotten tags — self-hiding: while shimmering, placeholder rows keep the
        // SAME list shape; otherwise only when there is at least one real tag.
        const showWeakTags = isSkeleton || weakTags.length > 0
        const weakTagItems: Array<SurfaceCardListItem> = isSkeleton
            ? Array.from({ length: SKELETON_WEAK_TAG_COUNT }, (_unused, index) => ({
                key: `pending-${index}`,
                title: "Tag",
                leadingIcon: WarningCircleIcon,
                leadingIconColor: "warning" as const,
                trailing: () => <Chip isSkeleton />,
            }))
            : weakTags.map((weak) => ({
                key: weak.tag,
                title: weak.tag,
                leadingIcon: WarningCircleIcon,
                leadingIconColor: "warning" as const,
                trailing: () => <Chip tone="danger" text={weak.forgotLabel} />,
            }))

        // session metric tiles — same 4-cell grid shape while shimmering (MetricCard's own
        // isSkeleton branch has no real value/label to check yet).
        const metricItems: Array<GridItem> = [
            {
                key: "total",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricTotalValue} label={labels.metricTotalLabel} />),
            },
            {
                key: "duration",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricDurationValue} label={labels.metricDurationLabel} />),
            },
            {
                key: "next-due",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricNextDueValue} label={labels.metricNextDueLabel} />),
            },
            {
                key: "xp",
                content: ({ isSkeleton: cellSkeleton }: SkeletonProps) => (cellSkeleton
                    ? <MetricCard isSkeleton />
                    : <MetricCard value={metricXpValue} label={labels.metricXpLabel} />),
            },
        ]

        contentNode = (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                isSkeleton={isSkeleton} items={[
                // HERO — the 4-grade SM-2 distribution (outcome first).
                    () => (
                        <SurfaceCard isSkeleton={isSkeleton} body={() => (
                            <StackV gap={5} principle="group-boundary"
                                explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                isSkeleton={isSkeleton} items={[
                                    () => (
                                        <StackV gap={3} principle="sibling-stack"
                                            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                            isSkeleton={isSkeleton} items={gradeRows.map((row) => () => (
                                                <StackH gap={3} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    isSkeleton={isSkeleton} items={[
                                                        () => <Typography size="sm" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={row.label} />,
                                                        () => (
                                                            <FillAvailable
                                                                at="base"
                                                                isSkeleton={isSkeleton}
                                                                body={() => (isSkeleton
                                                                    ? <ProgressMeter isSkeleton color={row.color} />
                                                                    : <ProgressMeter value={row.count} max={gradeTotal} color={row.color} />)}
                                                            />
                                                        ),
                                                        () => <Typography size="sm" color="muted" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={row.countPercentLabel} />,
                                                    ]} />
                                            ))} />
                                    ),
                                    // subtle secondary rollup — never replaces the 4 grades above
                                    () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.rollupLabel} />,
                                ]} />
                        )} />
                    ),

                    // session metric tiles
                    () => (
                    // teacher-hold: flashcards-remain-session-stats-metric-grid-gap4-no-token —
                    // four metric tiles at preserved step 4; no card-grid token.
                        <Section
                            header={{ title: labels.metricsLabel, level: 3 }}
                            isSkeleton={isSkeleton}
                            body={() => <Grid columns={{ base: 2, md: 4 }} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                isSkeleton={isSkeleton} items={metricItems} />}
                        />
                    ),

                    // most-forgotten tags — grouped from grade-0 cards
                    ...(showWeakTags ? [() => (
                        <SurfaceCardList label={labels.weakTagsHeading} isSkeleton={isSkeleton} items={weakTagItems} />
                    )] : []),

                    // PRIMARY payoff — self-hiding RAG "study your weak spot" list, keyed off the
                    // weak tags. RelatedContentList is a real block (self-fetching) — a presentational
                    // component may render a connected child (split.md). Hidden while shimmering (it
                    // fetches its own state).
                    ...(!isSkeleton ? [() => (
                        <RelatedContentList
                            courseId={courseId}
                            courseDisplayId={courseDisplayId}
                            query={relatedQuery}
                            label={labels.studyHeading}
                        />
                    )] : []),

                    // onward path — never a dead end, even with no weak tags
                    ...(!isSkeleton ? [() => (
                        <Button variant="tertiary" label={labels.backToReviewLabel} onPress={onBack} classNames={["self-center"]} />
                    )] : []),
                ]} />
        )
    }

    return (
        <StackV identity={{ tier: "page", component: "FlashcardSessionStats" }} gap={1} padding={{ base: { x: 5, y: 6 }, sm: { x: 6 } }} items={[
            () => (
                <Container size="md" padding={1} body={() => (
                    <StackV gap={6} principle="block-boundary"
                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[() => header, () => contentNode]}  />
                )} />
            ),
        ]} />
    )
}

import { InputSearch } from "@/components/atoms/forms"
import React from "react"
import { ListBox, ScrollShadow } from "@heroui/react"
import { CardsThreeIcon, MicrophoneStageIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"

import { StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { Box } from "@/components/frames/Box"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Placeholder row count the deck list shows while the first load is in flight. */
const SKELETON_ROW_COUNT = 5

/** Study mode vs quiz mode — the top mode switch. */
export type FlashcardStudyRailMode = "study" | "quiz"

/** One deck row, already resolved (sorted + search-filtered) by the connected `FlashcardStudyRail`. */
export interface FlashcardStudyRailDeck {
    id: string
    title: string
    dueCount?: number
}

/** All display text, already localized by the connected `FlashcardStudyRail`; a story passes i18n keys. */
export interface FlashcardStudyRailLabels {
    /** Accessible name for the mode-switch tab list. */
    modeAria: string
    modeStudy: string
    modeQuiz: string
    /** Visible caption above the deck search box, and the deck list's accessible name. */
    decksLabel: string
    /** Accessible name for the search box (falls back to the placeholder, matching the pre-split behaviour). */
    searchAria: string
    searchPlaceholder: string
    /** Empty-state title — the connected file already picks between the generic and the "no match for <query>" phrasing. */
    emptyTitle: string
    errorTitle: string
}

/** Props for {@link _FlashcardStudyRail} — presentational; all data resolved, no fetch/store/i18n. */
export interface FlashcardStudyRailProps extends WithClassNames<undefined> {
    /** First load, nothing in hand → the deck list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no deck to show (search narrowed the list to nothing, or the course has none). */
    isEmpty?: boolean
    /** Truthy → the error message (beats a stale loading flag). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch — the connected file's SWR `mutate`. */
    onRetry?: () => void
    mode: FlashcardStudyRailMode
    onModeChange: (mode: FlashcardStudyRailMode) => void
    /** Deck-search box value — study mode only. */
    query: string
    onQueryChange: (query: string) => void
    /** The deck highlighted in the rail (none during the cross-deck due session). */
    activeDeckId: string | null
    /** Already sorted + search-filtered decks. */
    decks: Array<FlashcardStudyRailDeck>
    onSelectDeck: (deckId: string) => void
    labels: FlashcardStudyRailLabels
}

/**
 * The flashcards LEFT RAIL — the same docs-style sidebar as the content-map rail
 * (pinned header + scroll region, full rail height). A mode switch (Study / Quiz)
 * + the course's decks as a searchable nav list; all selection drives the URL
 * (owned by the connected file), so the rail (layout) and the work pane (page)
 * share one source of truth. Presentational half of {@link FlashcardStudyRail}
 * (`tiers/split.md`): the deck list threads `isSkeleton` to every leaf so the
 * shimmer mirrors the loaded shape (loading-and-skeleton.md) instead of a
 * separate hand-kept skeleton tree — `error` beats a stale loading flag,
 * `isEmpty` is only read once settled.
 *
 * The deck list still composes HeroUI's `ListBox`/`ScrollShadow` directly: no
 * design-system atom wraps a selectable nav list or a shadowed scroll region
 * yet (the same gap the sibling `PracticeRail`/`ArchitectureRail` rails carry),
 * so this is a genuine vocabulary gap rather than a shape to invent here.
 *
 * @param props - {@link FlashcardStudyRailProps}
 */
export const _FlashcardStudyRail = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    mode,
    onModeChange,
    query,
    onQueryChange,
    activeDeckId,
    decks,
    onSelectDeck,
    labels,
    className,
}: FlashcardStudyRailProps) => {
    // placeholder rows while shimmering keep the SAME ListBox + row shape as the real decks —
    // only the leaves (Typography/Chip) switch to their own shimmer (loading-and-skeleton.md).
    const rows: Array<FlashcardStudyRailDeck> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({ id: `skeleton-${index}`, title: "" }))
        : decks

    /** error → skeleton/content → empty, in priority order (loading-and-skeleton.md). */
    const renderDeckRegion = () => {
        if (error) {
            return <AsyncContentError title={labels.errorTitle} onRetry={onRetry} />
        }
        if (!isSkeleton && isEmpty) {
            return <AsyncContentEmpty title={labels.emptyTitle} />
        }
        return (
            <ListBox
                aria-label={labels.decksLabel}
                selectionMode="single"
                selectedKeys={activeDeckId ? [activeDeckId] : []}
                onSelectionChange={(keys) => {
                    // rows are placeholders while shimmering — nothing real to select onto
                    if (isSkeleton) return
                    const key = [...keys][0]
                    if (typeof key === "string") {
                        onSelectDeck(key)
                    }
                }}
                className="p-0"
            >
                {rows.map((deck) => (
                    <ListBox.Item
                        key={deck.id}
                        id={deck.id}
                        textValue={deck.title}
                        className="cursor-pointer rounded-2xl data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft"
                    >
                        <Box principle="control-pad" className="px-3 py-2"
                            explain="Control hit-area inset — not row-pad, because this pads a single interactive control rather than a full content row.">
                            <Cluster gap={3} principle="value-row"
                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                justify="between" align="center" classNames={["w-full", "min-w-0"]} items={[
                                    () => (
                                        <Typography
                                            size="sm"
                                            truncate
                                            isSkeleton={isSkeleton}
                                            classNames={["min-w-0", "flex-1"]}
                                            text={deck.title}
                                        />
                                    ),
                                    () => (isSkeleton || deck.dueCount ? (
                                        <Chip
                                            isSkeleton={isSkeleton}
                                            tone="warning"
                                            text={deck.dueCount}
                                            classNames={["shrink-0"]}
                                        />
                                    ) : null),
                                ]} />
                        </Box>
                    </ListBox.Item>
                ))}
            </ListBox>
        )
    }

    return (
        <Box
            identity={{ tier: "block", component: "FlashcardStudyRail" }}
            principle="page-pad"
            explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
            className={`relative flex min-h-0 min-w-0 flex-col p-6${className ? ` ${className}` : ""}`}
        >
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                classNames={["min-h-0", "min-w-0", "flex-1"]} items={[
                    () => (
                        <StackV gap={4} items={[
                            () => (
                                <TabsCard
                                    variant="primary"
                                    leftTabs={{
                                        selectedKey: mode,
                                        ariaLabel: labels.modeAria,
                                        onSelectionChange: (key) => {
                                            if (key === "study" || key === "quiz") {
                                                onModeChange(key)
                                            }
                                        },
                                        items: [
                                            {
                                                key: "study",
                                                icon: <CardsThreeIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                label: labels.modeStudy,
                                            },
                                            {
                                                key: "quiz",
                                                icon: <MicrophoneStageIcon className="size-4 shrink-0" aria-hidden focusable="false" />,
                                                label: labels.modeQuiz,
                                            },
                                        ],
                                    }}
                                />
                            ),
                            ...(mode === "study" ? [() => (
                                <InputSearch
                                    label={labels.decksLabel}
                                    ariaLabel={labels.searchAria}
                                    placeholder={labels.searchPlaceholder}
                                    value={query}
                                    onValueChange={onQueryChange}
                                />
                            )] : []),
                        ]} />
                    ),
                    ...(mode === "study" ? [() => (
                        <ScrollShadow hideScrollBar className="min-h-0 min-w-0 flex-1 overflow-y-auto">
                            {renderDeckRegion()}
                        </ScrollShadow>
                    )] : []),
                ]} />
        </Box>
    )
}

"use client"

import React, { useEffect, useState } from "react"
import useSWR from "swr"
import { useLocale, useTranslations } from "next-intl"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import { EnrollGate } from "@/components/blocks/learn/EnrollGate"
import { LearnBreadcrumb } from "@/components/blocks/learn/LearnBreadcrumb"
